You are working in /tmp/sv-3af4e7ea258640f8a9623c0156fa339e/ShipmentTracker. This is a Blazor Web App with Interactive Auto (global) and Individual authentication. The solution has two projects:
- ShipmentTracker (server) 
- ShipmentTracker.Client (WebAssembly)

The task: Implement a logistics shipment tracking app. Remove default Counter.razor and Weather.razor pages. Keep Auth.razor, NotFound.razor, Home.razor (modify Home).

## What to build:

### 1. Shared Model (in .Client project since interactive components need it)
Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string Status { get; set; } = "Pending";
    public DateTime? EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
}
```

### 2. Service Interface (in .Client project)
Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<Shipment> CreateShipmentAsync(Shipment shipment);
    Task<Shipment> UpdateShipmentStatusAsync(int id, string status);
}
```

### 3. Client Implementation (HttpClient-based, in .Client project)
Create `ShipmentTracker.Client/Services/ShipmentHttpService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

public class ShipmentHttpService : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentHttpService(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await _http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? new();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var response = await _http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (response.IsSuccessStatusCode)
            return await response.Content.ReadFromJsonAsync<Shipment>();
        return null;
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        var response = await _http.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>() ?? shipment;
    }

    public async Task<Shipment> UpdateShipmentStatusAsync(int id, string status)
    {
        var response = await _http.PutAsJsonAsync($"api/shipments/{id}/status", new { Status = status });
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>() ?? new();
    }
}
```

### 4. Server Implementation (in server project)
Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
namespace ShipmentTracker.Services;

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

public class ShipmentServerService : IShipmentService
{
    private static readonly List<Shipment> _shipments = new()
    {
        new() { Id = 1, TrackingNumber = "TRK-001-2026", Origin = "New York, US", Destination = "London, UK", Status = "In Transit", EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "alice@example.com", CreatedAt = DateTime.UtcNow.AddDays(-2) },
        new() { Id = 2, TrackingNumber = "TRK-002-2026", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = "Customs", EstimatedDelivery = DateTime.UtcNow.AddDays(5), CustomerEmail = "bob@example.com", CreatedAt = DateTime.UtcNow.AddDays(-5) },
        new() { Id = 3, TrackingNumber = "TRK-003-2026", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = "Delivered", EstimatedDelivery = DateTime.UtcNow.AddDays(-1), CustomerEmail = "carol@example.com", CreatedAt = DateTime.UtcNow.AddDays(-10) },
        new() { Id = 4, TrackingNumber = "TRK-004-2026", Origin = "Sydney, AU", Destination = "Mumbai, IN", Status = "Pending", EstimatedDelivery = DateTime.UtcNow.AddDays(7), CustomerEmail = "dave@example.com", CreatedAt = DateTime.UtcNow.AddDays(-1) },
        new() { Id = 5, TrackingNumber = "TRK-005-2026", Origin = "São Paulo, BR", Destination = "Paris, FR", Status = "In Transit", EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "eve@example.com", CreatedAt = DateTime.UtcNow.AddDays(-3) },
    };
    private static int _nextId = 6;

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        shipment.Id = _nextId++;
        shipment.CreatedAt = DateTime.UtcNow;
        _shipments.Add(shipment);
        return Task.FromResult(shipment);
    }

    public Task<Shipment> UpdateShipmentStatusAsync(int id, string status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is null) throw new InvalidOperationException($"Shipment {id} not found");
        shipment.Status = status;
        return Task.FromResult(shipment);
    }
}
```

### 5. API Endpoints (add to server Program.cs)
Add these minimal API endpoints BEFORE `app.Run();` in the server `Program.cs`. Also register `IShipmentService` as singleton `ShipmentServerService` in the server DI, and register `IShipmentService` as `ShipmentHttpService` with a named HttpClient in the client `Program.cs`.

Server Program.cs additions (add service registration after the Identity services, before `var app = ...`):
```csharp
builder.Services.AddSingleton<ShipmentTracker.Client.Services.IShipmentService, ShipmentTracker.Services.ShipmentServerService>();
```

Add API endpoints before `app.Run();`:
```csharp
// Shipment API endpoints
var shipmentApi = app.MapGroup("api/shipments").RequireAuthorization();

shipmentApi.MapGet("/", async (ShipmentTracker.Client.Services.IShipmentService service) =>
    Results.Ok(await service.GetAllShipmentsAsync()));

shipmentApi.MapGet("/track/{trackingNumber}", async (string trackingNumber, ShipmentTracker.Client.Services.IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
}).AllowAnonymous();

shipmentApi.MapPost("/", async (ShipmentTracker.Client.Models.Shipment shipment, ShipmentTracker.Client.Services.IShipmentService service) =>
    Results.Created($"/api/shipments/{shipment.Id}", await service.CreateShipmentAsync(shipment)));

shipmentApi.MapPut("/{id}/status", async (int id, ShipmentTracker.Client.Services.StatusUpdateRequest request, ShipmentTracker.Client.Services.IShipmentService service) =>
    Results.Ok(await service.UpdateShipmentStatusAsync(id, request.Status)));
```

Also create `ShipmentTracker.Client/Services/StatusUpdateRequest.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

public class StatusUpdateRequest
{
    public string Status { get; set; } = string.Empty;
}
```

Client Program.cs - add before `await builder.Build().RunAsync();`:
```csharp
builder.Services.AddHttpClient<ShipmentTracker.Client.Services.IShipmentService, ShipmentTracker.Client.Services.ShipmentHttpService>(
    client => client.BaseAddress = new Uri(builder.HostEnvironment.BaseAddress));
builder.Services.AddScoped<ShipmentTracker.Client.Services.IShipmentService>(sp =>
    sp.GetRequiredService<IHttpClientFactory>().CreateClient(nameof(ShipmentTracker.Client.Services.IShipmentService))
    .Let(http => new ShipmentTracker.Client.Services.ShipmentHttpService(http)));
```

Actually, simpler approach for client Program.cs:
```csharp
builder.Services.AddScoped(sp => new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });
builder.Services.AddScoped<ShipmentTracker.Client.Services.IShipmentService, ShipmentTracker.Client.Services.ShipmentHttpService>();
```

### 6. Pages (in .Client project)

**Modify `ShipmentTracker.Client/Pages/Home.razor`** to be a welcome/landing page:
```razor
@page "/"

<PageTitle>ShipmentTracker - Logistics Management</PageTitle>

<div class="text-center">
    <h1>Welcome to ShipmentTracker</h1>
    <p class="lead">Real-time logistics management for dispatchers and customers.</p>

    <div class="row mt-4">
        <div class="col-md-6">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">📦 Track a Shipment</h5>
                    <p class="card-text">Enter your tracking number to check status and estimated delivery.</p>
                    <a href="/track" class="btn btn-primary">Track Now</a>
                </div>
            </div>
        </div>
        <div class="col-md-6">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">🚚 Dispatcher Dashboard</h5>
                    <p class="card-text">View and manage all shipments, update statuses, and create new shipments.</p>
                    <a href="/shipments" class="btn btn-secondary">Go to Dashboard</a>
                </div>
            </div>
        </div>
    </div>
