    public Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        shipment.Id = _nextId++;
        shipment.CreatedAt = DateTime.UtcNow;
        _shipments.Add(shipment);
        return Task.FromResult(shipment);
    }

    public Task<Shipment> UpdateShipmentStatusAsync(int id, string status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is null) throw new InvalidOperationException($"Shipment {id} not found");
        shipment.Status = status;
        return Task.FromResult(shipment);
    }
}
```

