    private List<Shipment> _shipments = new();
    private bool _loading = true;
    private string _filterText = string.Empty;
    private string _statusFilter = string.Empty;
    private bool _showCreateForm;
    private Shipment _newShipment = new();

    private IEnumerable<Shipment> FilteredShipments => _shipments
        .Where(s => string.IsNullOrEmpty(_filterText) || s.Destination.Contains(_filterText, StringComparison.OrdinalIgnoreCase))
        .Where(s => string.IsNullOrEmpty(_statusFilter) || s.Status == _statusFilter);

    protected override async Task OnInitializedAsync()
    {
        _shipments = await ShipmentService.GetAllShipmentsAsync();
        _loading = false;
    }

    private void ShowCreateForm()
    {
        _showCreateForm = true;
        _newShipment = new Shipment
        {
            TrackingNumber = $"TRK-{Random.Shared.Next(100, 999)}-{DateTime.UtcNow.Year}",
            EstimatedDelivery = DateTime.UtcNow.AddDays(7)
        };
    }

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(_newShipment.Origin) || string.IsNullOrWhiteSpace(_newShipment.Destination))
            return;

        var created = await ShipmentService.CreateShipmentAsync(_newShipment);
        _shipments.Add(created);
        _showCreateForm = false;
    }

    private async Task UpdateStatus(int id, string newStatus)
    {
        var updated = await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
        var index = _shipments.FindIndex(s => s.Id == id);
        if (index >= 0) _shipments[index] = updated;
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-warning text-dark",
        "In Transit" => "bg-info text-dark",
        "Customs" => "bg-secondary",
        "Delivered" => "bg-success",
        _ => "bg-light text-dark"
    };
}
