+@page "/track"
+@page "/track/{TrackingNumber}"
+@using ShipmentTracker.Client.Models
+@using ShipmentTracker.Client.Services
+@inject IShipmentService ShipmentService
+
+<PageTitle>Track Your Shipment</PageTitle>
+
+<h1>Track Your Shipment</h1>
+
+<div class="row mb-4">
+    <div class="col-md-6">
+        <div class="input-group">
+            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-001-2026)"
+                   @bind="_searchTrackingNumber" @onkeydown="HandleKeyDown" />
+            <button class="btn btn-primary" @onclick="SearchShipment">Track</button>
+        </div>
+    </div>
+</div>
+
+@if (_searching)
+{
+    <p><em>Searching...</em></p>
+}
+else if (_searched && _shipment is null)
+{
+    <div class="alert alert-warning">
+        No shipment found with tracking number "<strong>@_lastSearched</strong>". Please check the number and try again.
+    </div>
+}
+else if (_shipment is not null)
+{
+    <div class="card">
+        <div class="card-header">
+            <h5 class="mb-0">Shipment: @_shipment.TrackingNumber</h5>
+        </div>
+        <div class="card-body">
+            <div class="row">
+                <div class="col-md-6">
+                    <dl>
+                        <dt>Status</dt>
+                        <dd><span class="badge @GetStatusBadgeClass(_shipment.Status) fs-6">@_shipment.Status</span></dd>
+
+                        <dt>Origin</dt>
+                        <dd>@_shipment.Origin</dd>
+
+                        <dt>Destination</dt>
+                        <dd>@_shipment.Destination</dd>
+                    </dl>
+                </div>
+                <div class="col-md-6">
+                    <dl>
+                        <dt>Estimated Delivery</dt>
+                        <dd>
+                            @if (_shipment.EstimatedDelivery.HasValue)
+                            {
+                                <span class="fs-5">@_shipment.EstimatedDelivery.Value.ToString("dddd, MMMM dd, yyyy")</span>
+                                @if (_shipment.EstimatedDelivery.Value > DateTime.UtcNow)
+                                {
+                                    <br/><small class="text-muted">(@((int)(_shipment.EstimatedDelivery.Value - DateTime.UtcNow).TotalDays) days remaining)</small>
+                                }
+                            }
+                            else
+                            {
+                                <span>Not yet estimated</span>
+                            }
+                        </dd>
+
+                        <dt>Shipped On</dt>
+                        <dd>@_shipment.CreatedAt.ToString("MMMM dd, yyyy")</dd>
+                    </dl>
+                </div>
+            </div>
+        </div>
+    </div>
+}
+
+@code {
+    [Parameter]
+    public string? TrackingNumber { get; set; }
+
+    private string _searchTrackingNumber = string.Empty;
+    private string _lastSearched = string.Empty;
+    private Shipment? _shipment;
+    private bool _searching;
+    private bool _searched;
+
+    protected override async Task OnInitializedAsync()
+    {
+        if (!string.IsNullOrEmpty(TrackingNumber))
+        {
+            _searchTrackingNumber = TrackingNumber;
+            await SearchShipment();
+        }
+    }
+
+    private async Task SearchShipment()
+    {
+        if (string.IsNullOrWhiteSpace(_searchTrackingNumber)) return;
+
+        _searching = true;
+        _searched = false;
+        _shipment = null;
+        StateHasChanged();
+
+        _lastSearched = _searchTrackingNumber.Trim();
+        _shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(_lastSearched);
+        _searching = false;
+        _searched = true;
+    }
+
+    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter")
+            await SearchShipment();
+    }
+
