    {
        <div class="card mb-3">
            <div class="card-body">
                <h5>Create New Shipment</h5>
                <div class="row g-2">
                    <div class="col-md-3">
                        <input type="text" class="form-control" placeholder="Origin" @bind="_newShipment.Origin" />
                    </div>
                    <div class="col-md-3">
                        <input type="text" class="form-control" placeholder="Destination" @bind="_newShipment.Destination" />
                    </div>
                    <div class="col-md-3">
                        <input type="email" class="form-control" placeholder="Customer Email" @bind="_newShipment.CustomerEmail" />
                    </div>
                    <div class="col-md-3">
                        <button class="btn btn-primary" @onclick="CreateShipment">Create</button>
                        <button class="btn btn-outline-secondary" @onclick="() => _showCreateForm = false">Cancel</button>
                    </div>
                </div>
            </div>
        </div>
    }

    <table class="table table-striped">
