@code {
    [Parameter]
    public string? TrackingNumber { get; set; }

    private string _searchTrackingNumber = string.Empty;
    private string _lastSearched = string.Empty;
    private Shipment? _shipment;
    private bool _searching;
    private bool _searched;

    protected override async Task OnInitializedAsync()
    {
        if (!string.IsNullOrEmpty(TrackingNumber))
        {
            _searchTrackingNumber = TrackingNumber;
            await SearchShipment();
        }
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(_searchTrackingNumber)) return;

        _searching = true;
        _searched = false;
        _shipment = null;
        StateHasChanged();

        _lastSearched = _searchTrackingNumber.Trim();
        _shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(_lastSearched);
        _searching = false;
        _searched = true;
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-warning text-dark",
        "In Transit" => "bg-info text-dark",
        "Customs" => "bg-secondary",
        "Delivered" => "bg-success",
        _ => "bg-light text-dark"
    };
}
```

